        raise ValueError("interval tem de ser >= 1")

    out = [rec.start]
    k = 1
    while len(out) < count:
        if rec.kind == "daily":
            out.append(rec.start + timedelta(days=rec.interval * k))
        elif rec.kind == "weekly":
            out.append(rec.start + timedelta(weeks=rec.interval * k))
        elif rec.kind == "monthly":
            out.append(add_months(rec.start, rec.interval * k))
        else:
            raise ValueError(f"kind desconhecido: {rec.kind}")
        k += 1
    return out


def business_days_between(a: date, b: date) -> int:
    """Numero de dias uteis (seg-sex) no intervalo [a, b), a < b."""
    if b <= a:
        return 0
    days = 0
    cur = a
    while cur < b:
        if cur.weekday() < 5:
            days += 1
        cur += timedelta(days=1)
    return days


